class Solution { public:int numberOfGoodPartitions(vector<int>& nums){const long long MOD=1000000007;unordered_map<int,int> last;for(int i=0;i<(int)nums.size();++i)last[nums[i]]=i;int components=0,farthest=0;for(int i=0;i<(int)nums.size();++i){farthest=max(farthest,last[nums[i]]);if(i==farthest)++components;}long long answer=1,base=2;int exponent=components-1;while(exponent){if(exponent&1)answer=answer*base%MOD;base=base*base%MOD;exponent>>=1;}return answer;} };
